import sys

data = sys.stdin.read().split()
n, m, E, s, t = (int(x) for x in data[:5])
k = int(data[5])
drink = [False] * n
for i in range(k):
    drink[int(data[6 + i])] = True
pos = 6 + k
adj = [[] for _ in range(n)]
for i in range(m):
    u, v = int(data[pos + 2 * i]), int(data[pos + 2 * i + 1])
    adj[u].append(v)
    adj[v].append(u)
if s == t:
    print(0)
else:
    cur = {(s, E)}
    seen = set(cur)
    ans = -1
    for step in range(1, n * (E + 1) + 2):
        nxt = set()
        found = False
        for (u, e) in cur:
            if e < 1:
                continue
            for v in adj[u]:
                if v == t:
                    found = True
                    continue
                ne = e - 1
                if drink[v]:
                    ne = E
                if ne == 0:
                    continue
                if (v, ne) not in seen:
                    seen.add((v, ne))
                    nxt.add((v, ne))
        if found:
            ans = step
            break
        if not nxt:
            break
        cur = nxt
    print(ans)

